&lt;div id=&quot;toc&quot; class=&quot;toc&quot;&gt;
&lt;div id=&quot;toctitle&quot;&gt;İçindekiler&lt;/div&gt;
&lt;ul class=&quot;sectlevel1&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_sorun_bana_zaman_kaybettiren_üç_mimari&quot;&gt;Sorun: Bana Zaman Kaybettiren Üç Mimari&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
&lt;li&gt;&lt;a href=&quot;#_seçenek_1_i̇zole_eklenti_dogfooding_yok&quot;&gt;Seçenek 1: İzole Eklenti (dogfooding yok)&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_seçenek_2_klasik_monorepo_includeplugin&quot;&gt;Seçenek 2 : Klasik Monorepo (&lt;code&gt;include(&quot;:plugin&quot;)&lt;/code&gt;)&lt;/a&gt;&lt;/li&gt;
