&lt;li&gt;&lt;a href=&quot;#_zoom_font_size_bileşenler_listesi_için&quot;&gt;zoom` &amp;gt; &lt;code&gt;font-size&lt;/code&gt; bileşenler listesi için&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_custom_css_uzantısı_açıkça_etkinleştirilmesi_gerekiyor&quot;&gt;Custom CSS uzantısı açıkça etkinleştirilmesi gerekiyor&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_bir_güncelleme_komut_dosyası_zorunludur&quot;&gt;Bir güncelleme komut dosyası zorunludur&lt;/a&gt;&lt;/li&gt;
