&lt;li&gt;&lt;a href=&quot;#_adım_2_head_içindeki_ön_yükleme_betiği&quot;&gt;Adım 2 : &amp;lt;head&amp;gt; içindeki ön yükleme betiği&lt;/a&gt;
&lt;ul class=&quot;sectlevel2&quot;&gt;
