&lt;p&gt;&lt;a href=&quot;https://www.slf4j.org/manual.html&quot;&gt;SLF4J Kılavuz&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://logback.qos.ch/manual/configuration.html&quot;&gt;Logback yapılandırması&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://github.com/gradle/gradle/tree/master/subprojects/test-kit&quot;&gt;Gradle TestKit Kaynak Kodu&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
