&lt;li&gt;&lt;a href=&quot;#_3_değerlendirme_geri_çağırmalarını_taklit_edin&quot;&gt;3. Değerlendirme geri çağırmalarını taklit edin&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_4_yol_çözümlemesini_test_et&quot;&gt;4. Yol çözümlemesini test et&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_final_test_mimarisi&quot;&gt;Final test mimarisi&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&quot;#_sonuç&quot;&gt;Sonuç&lt;/a&gt;&lt;/li&gt;
