&lt;li&gt;&lt;a href=&quot;#_başka_bir_dizinden_belirli_bir_projede_bir_görev_başlat&quot;&gt;Başka bir dizinden belirli bir projede bir görev başlat&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_yardımı_göster&quot;&gt;Yardımı göster&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;./gradlew --help&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_jvm_sistem_özelliğini_tanımla_d_system_prop&quot;&gt;JVM sistem özelliğini tanımla : `-D, --system-prop&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;./gradlew -Dmyprop=myvalue
#ou
./gradlew --system-prop myvalue&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_proje_özelliğini_derleme_betiği_için_ayarlayın_pmypropmyvalue&quot;&gt;Proje özelliğini derleme betiği için ayarlayın: `-Pmyprop=myvalue&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;./gradlew -Pmyprop=myvalue
#ou
./gradlew --project-prop myvalue&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_gradle_başlangıç_dizinini_belirtir_varsayılan_değer_geçerli_dizindir&quot;&gt;Gradle başlangıç dizinini belirtir. Varsayılan değer geçerli dizindir.&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;./gradlew -p ~/src/next_startup
#ou
./gradlew --project-dir ~/src/next_startup&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_komut_satırından_param_component_özelliğini_geçersiz_kılın&quot;&gt;Komut satırından &lt;code&gt;param_component&lt;/code&gt; özelliğini geçersiz kılın :&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;./gradlew -Pparam_component=CUSTOM_VALUE&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_kotlin_dsl_ile_normal_bir_projede_source_sete_bir_klasör_eklemek&quot;&gt;Kotlin DSL ile normal bir projede source-set&amp;#8217;e bir klasör eklemek&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;sourceSets {
    getByName(&quot;test&quot;){
        java.srcDir(&quot;src/scripts/groovy&quot;)
    }
    getByName(&quot;test&quot;){
        java.srcDir(&quot;src/scripts/kscript&quot;)
    }
    getByName(&quot;test&quot;){
        java.srcDir(&quot;src/test/javascript&quot;)
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_groovy_dsl_kullanarak_android_projedeki_bir_source_sete_bir_klasör_ekle&quot;&gt;Groovy DSL kullanarak Android projedeki bir source-set&amp;#8217;e bir klasör ekle&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;android {
    sourceSets {
        main.java.srcDirs += &quot;src/main/../../../../ceelo/domain/src/main/java/&quot;
        test.java.srcDirs += &quot;src/test/../../../../ceelo/domain/src/test/java/&quot;
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_bir_alt_modül_oluşturup_test_etmeyi_kaçının&quot;&gt;Bir alt modül oluşturup test etmeyi kaçının&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;gradle build -x :excluded-module:check -x :excluded-module:assemble -x :excluded-module:build&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Dosyaları taşı&lt;/div&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;tasks.register(&quot;moveWebappNode&quot;) {
    doLast {
        ant.withGroovyBuilder {
            &quot;move&quot;(
                &quot;webapp/node_modules&quot; to &quot;$rootDir/webapp-src/node_modules&quot;,
            )
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_tar_bir_dosya&quot;&gt;Tar bir dosya&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;tasks.register&amp;lt;Tar&amp;gt;(&quot;tarWebapp&quot;) {
    dependsOn(&quot;moveWebappNpm&quot;)
    group = WEBAPP
    description = &quot;tar webapp&quot;
    doLast {
        setOf(
            &quot;build&quot;,
            &quot;target&quot;,
            &quot;node_modules&quot;
        ).forEach { dir -&amp;gt; exclude { it.name .dir } }
        archiveFileName.set(&quot;webapp.tar&quot;)
        destinationDirectory.set(File(&quot;${rootDir.absolutePath}$sep$WEBAPP_SRC&quot;))
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_bir_derlemenin_bağımlılıklarını_göster&quot;&gt;Bir derlemenin bağımlılıklarını göster&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;tasks.register(&quot;printDependencies&quot;) {
    description = &quot;print project dependencies&quot;
    group = WEBAPP
    doLast {
        println(&quot;${project.name} dependencies&quot;)
        mutableMapOf&amp;lt;String, Map&amp;lt;String, String&amp;gt;&amp;gt;(
            &quot;buildDependencies&quot; to buildDependencies,
            &quot;domainDeps&quot; to domainDeps,
            &quot;domainTestDeps&quot; to domainTestDeps,
        ).apply { putAll(appModules) }
            .forEach { module -&amp;gt;
                if (module.value.isNotEmpty()) {
                    println(&quot;${module.key}:&quot;)
                    module.value.forEach { println(dependency(it)) }
                    println()
                }
            }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_reduce_kullanım_örneği_bir_listeyi_bir_stringe_dönüştürme&quot;&gt;reduce kullanım örneği : bir listeyi bir stringe dönüştürme&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;tasks.register(&quot;printWebappSrc&quot;) {
    description = &quot;print webapp sources&quot;
    group = WEBAPP
    doLast {
        webAppSrc
            .reduce { acc, s -&amp;gt; &quot;$acc\n\t$s&quot; }
            .run { println(&quot;$WEBAPP_SRC: $this\n&quot;) }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_belirli_bir_görevin_açıklamasıyı_al&quot;&gt;Belirli bir görevin açıklamasıyı al&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;./gradlew -q help --task foo&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_bir_görevi_workingdir_kökünden_başlatmak_için_ardından_görevi_bir_ile_öneki_yapın&quot;&gt;Bir görevi workingDir kökünden başlatmak için, ardından görevi bir &lt;code&gt;:&lt;/code&gt; ile öneki yapın.&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;./gradlew :foo&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_başarısız_olan_görevleri_yeniden_başlatmak_için_seçeneği_kullan_rerun_tasks&quot;&gt;Başarısız olan görevleri yeniden başlatmak için seçeneği kullan `--rerun-tasks&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;./gradlew check --rerun-tasks&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_başka_bir_dizinden_belirli_bir_projede_bir_görev_başlat&quot;&gt;Başka bir dizinden belirli bir projede bir görev başlat&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;seçenek`-p` (ou &lt;code&gt;--project-dir&lt;/code&gt;) Gradle projesinin yolunu belirtmek ve orada bir görev çalıştırmak için kullanılır, mevcut dizin farklı olsa bile.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Örneğin, görevi başlatmak için`build`projenin konumlandığı`~/projets/mon-autre-projet`autre bir dizindeyken :&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-bash&quot; data-lang=&quot;bash&quot;&gt;./gradlew -p ~/projets/mon-autre-projet build&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu birden fazla proje üzerinde eylemleri betiklemek için merkezi bir konumdan özellikle faydalıdır.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;div class=&quot;title&quot;&gt;Ayrıca bakınız :&lt;/div&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://docs.gradle.org/current/userguide/command_line_interface.html#sec:command_line_warnings&quot;&gt;referans&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://docs.gradle.org/current/userguide/command_line_interface.html#sec:command_line_options&quot;&gt;ref&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;&lt;a href=&quot;https://stackoverflow.com/a/36178581/837404&quot;&gt;tartışma&lt;/a&gt;&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;sealed sınıflar, numaralandırmalar(anahtar kelime:enum)&lt;br&gt;
Java&amp;#8217;dan geliyorsanız, özellik sağlayan numaralandırmasını aşırı yüklemeye yatkın olabilirsiniz. // Java kodu&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-java&quot; data-lang=&quot;java&quot;&gt;enum PizzaOrderStatus {
    ORDER_RECEIVED,
    PIZZA_BEING_MADE,
    OUT_FOR_DELIVERY,
    COMPLETED;
    public PizzaOrderStatus nextStatus() {
        switch (this) {
        case ORDER_RECEIVED: return PIZZA_BEING_MADE;
        case PIZZA_BEING_MADE: return OUT_FOR_DELIVERY;
        case OUT_FOR_DELIVERY: return COMPLETED;
        case COMPLETED:return COMPLETED;
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bunun yerine, sealed sınıfını kullanabilirsiniz:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;sealed class PizzaOrderStatus(protected val orderId: Int) {
    abstract fun nextStatus() : PizzaOrderStatus
    class OrderReceived(orderId: Int) : PizzaOrderStatus(orderId) {
        override fun nextStatus(): PizzaOrderStatus {
            return PizzaBeingMade(orderId)
        }
    }
    class PizzaBeingMade(orderId: Int) : PizzaOrderStatus(orderId) {
        override fun nextStatus(): PizzaOrderStatus {
            return OutForDelivery(orderId)
        }
    }
    class OutForDelivery(orderId: Int) : PizzaOrderStatus(orderId) {
        override fun nextStatus(): PizzaOrderStatus {
            return Completed(orderId)
        }
    }
    class Completed(orderId: Int) : PizzaOrderStatus(orderId) {
        override fun nextStatus(): PizzaOrderStatus {
            return this
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Bu yaklaşımın avantajı, artık verileriyle gönderebileceğimiz şey durum:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;var status: PizzaOrderStatus = OrderReceived(123)
while (status !is Completed) {
    status = when (status) {
        is OrderReceived -&amp;gt; status.nextStatus()
        is PizzaBeingMade -&amp;gt; status.nextStatus()
        is OutForDelivery -&amp;gt; status.nextStatus()
        is Completed -&amp;gt; status
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Genel olarak, sealed classlar, verileri bir şeyle ilişkilendirmek istiyorsanız iyi olur. Devlet.&lt;/p&gt;
&lt;/div&gt;

&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_zihin_haritası&quot;&gt;Zihin haritası&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;span class=&quot;image&quot;&gt;&lt;img src=&quot;../../diagram/training_kotlin.png&quot; alt=&quot;training_kotlin&quot;&gt;&lt;/span&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect1&quot;&gt;
&lt;h2 id=&quot;_i̇şlevsel_programlama&quot;&gt;İşlevsel programlama&lt;/h2&gt;
&lt;div class=&quot;sectionbody&quot;&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Alıştırma soruları kitabından alınmıştır:&lt;br&gt;
Kotlin&amp;#8217;de işlevsel programlama dersleri ile&lt;br&gt;
Massimo Carli tarafından yazıldı&lt;br&gt;
repo: &lt;a href=&quot;https://github.com/kodecocodes/fpk-materials&quot; class=&quot;bare&quot;&gt;https://github.com/kodecocodes/fpk-materials&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_sözdizimi&quot;&gt;sözdizimi&lt;/h3&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_firstprogramtest&quot;&gt;FirstProgramTest&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;kavramlar: ekran gösterimi, fonksiyon&lt;br&gt;
BirinciProgramTest:https://github.com/cheroliv/cheroliv.com/blob/master/codes/src/test/kotlin/programming/FirstProgramTest.kt[(Empty response)]&lt;br&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_concatfunctiontest&quot;&gt;ConcatFunctionTest&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;notions: bellek, değişken, değer, nesne, fonksiyon uzantısı&lt;br&gt;
(Note: Empty output as there was no provided source text to translate.)&lt;a href=&quot;https://github.com/cheroliv/cheroliv.com/blob/master/codes/src/test/kotlin/programming/ConcatFunctionTest.kt&quot;&gt;(no output - empty)&lt;/a&gt;&amp;lt;/think&amp;gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;+&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_birthdaymessagetestoutput&quot;&gt;BirthdayMessageTestOutput&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;kavramlar: kümeler, döngüler&lt;br&gt;
&lt;a href=&quot;https://developer.android.com/codelabs/basic-android-kotlin-training-first-kotlin-program?continue=https%3A%2F%2Fdeveloper.android.com%2Fcourses%2Fpathways%2Fandroid-basics-kotlin-one%23codelab-https%3A%2F%2Fdeveloper.android.com%2Fcodelabs%2Fbasic-android-kotlin-training-first-kotlin-program&quot;&gt;Kotlin&amp;#8217;e Giriş&lt;/a&gt;&lt;br&gt;
BirthdayMessageTestOutput:https://github.com/cheroliv/cheroliv.com/blob/master/codes/src/test/kotlin/programming/BirthdayMessageTestOutput.kt[kaynak]&lt;br&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_kotlin_dersi&quot;&gt;Kotlin dersi&lt;/h3&gt;
&lt;div class=&quot;videoblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;iframe src=&quot;https://www.youtube.com/embed/YRjY3jRrQYY?rel=0&quot; frameborder=&quot;0&quot; allowfullscreen&gt;&lt;/iframe&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_java_koleksiyonları_eğitimi&quot;&gt;Java koleksiyonları eğitimi&lt;/h3&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;&lt;a href=&quot;https://docs.oracle.com/javase/tutorial/collections/index.html&quot; target=&quot;_blank&quot; rel=&quot;noopener&quot;&gt;Koleksiyonlar&lt;/a&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Koleksiyon arayüzlerinin kalbi&lt;br&gt;
&lt;span class=&quot;image&quot;&gt;&lt;img src=&quot;../../img/0036_training_kotlin_post/colls-coreInterfaces.gif&quot; alt=&quot;Koleksiyonlar&quot;&gt;&lt;/span&gt;&lt;br&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_fonksiyonel_temeller&quot;&gt;Fonksiyonel temeller&lt;/h3&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_deklaratif_x_imperatif_yaklaşım&quot;&gt;Deklaratif X imperatif yaklaşım&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;package functional

import kotlin.test.Test
import kotlin.test.assertEquals

class DeclarativeTests {
    val input = listOf(
        &quot;123&quot;, &quot;abc&quot;, &quot;1ds&quot;, &quot;987&quot;, &quot;abdf&quot;, &quot;1d3&quot;, &quot;de1&quot;, &quot;88&quot;, &quot;101&quot;
    )

    fun imperativeSum(list: List&amp;lt;String&amp;gt;): Int {
        var sum = 0
        for (item in list) {
            try {
                sum += item.toInt()
            } catch (_: NumberFormatException) {
            }
        }
        return sum
    }

    @Test
    fun `test imperative approach`() {
        imperativeSum(input).run {
            println(&quot;Sum $this&quot;)
            assertEquals(1299, this)
        }
    }

    fun isValidNumber(s: String) = try {
        s.toInt()
        true
    } catch (_: NumberFormatException) {
        false
    }

    fun declarativeSum(list: List&amp;lt;String&amp;gt;) = list
        .filter(::isValidNumber)
        .map(String::toInt)
        .sum()

    @Test
    fun `test declarative approach`() {
        assertEquals(1299, declarativeSum(input).apply {
            println(&quot;Sum $this&quot;)
        })
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_alıştırma_1_1&quot;&gt;Alıştırma 1.1&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;sumInRange fonksiyonu uygulayın; bu fonksiyon, içinde değerleri toplar.&lt;br&gt;
Verilen bir aralıkta bir List&amp;lt;String&amp;gt;. İmzası şu şekildedir:&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;fun sumInRange(input: List&amp;lt;String&amp;gt;, range: IntRange): Int&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;@Test
fun `Exercise 1_1`() {
    assertEquals(4, sumInRange(
        listOf(&quot;1&quot;, &quot;10&quot;, &quot;a&quot;, &quot;7&quot;, &quot;ad2&quot;, &quot;3&quot;),
            1..5
        ).apply { println(&quot;sumInRange 1..5: $this&quot;) }
    )
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Deneyin ve cevabınızı ile kontrol edinhttps://github.com/cheroliv/cheroliv.com/blob/master/codes/src/test/kotlin/functional/DeclarativeTests.kt[çözüm, windows=&quot;_blank].&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_yüksek_derecede_fonksiyonlar&quot;&gt;Yüksek derecede fonksiyonlar&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;package functional

import java.io.ByteArrayOutputStream
import java.io.PrintStream
import java.lang.System.*
import java.lang.Thread.sleep
import kotlin.math.sign
import kotlin.test.Test
import kotlin.test.assertEquals

class BasicsHOFTests {
    val ONE_SECOND = 1000L

    @Test
    fun `high order function`() {
        //capture de la sortie standard
        val standardOut: PrintStream? = out
        val outputStreamCaptor = ByteArrayOutputStream()
        setOut(PrintStream(outputStreamCaptor))

        3.times { println(&quot;Hello&quot;) }
        assertEquals(
            buildString {
                repeat(3) { append(&quot;Hello\n&quot;) }
                deleteAt(length - 1)
            }, outputStreamCaptor
                .toString()
                .trim()
        )

        //libération de la sortie standard
        setOut(standardOut)
    }

    fun Int.times1(fn: () -&amp;gt; Unit) {
        for (i in 1..this) {
            fn()
        }
    }

    fun Int.times2(fn: () -&amp;gt; Unit) {
        for (i in 1..this) fn()
    }

    fun Int.times3(fn: () -&amp;gt; Unit) =
        (1..this).forEach { fn() }


    fun Int.times4(fn: () -&amp;gt; Unit) =
        repeat((1..this).count()) { fn() }

    fun Int.times(fn: () -&amp;gt; Unit) =
        (1..this).forEach { _ -&amp;gt; fn() }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_alıştırma_1_2&quot;&gt;Alıştırma 1.2&lt;/h4&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Tipi olan bir fonksiyonu kabul eden kronometriyı uygulayın`() &amp;#8594;`&lt;br&gt;
Giriş alır ve çalıştırma süresini döndürür. İmzası şu şekildedir:&lt;br&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;fun chrono(fn : () -&amp;gt; Unité) : Long&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;@Test
fun `Exercise 1_2`() {
    val waitOneSec = { sleep(ONE_SECOND) }
    chrono(waitOneSec).apply {
        println(&quot;chrono: $this&quot;)
        assertEquals(1, sign)
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Deneyip cevabını la ile kontrol edinhttps://github.com/cheroliv/cheroliv.com/blob/master/codes/src/test/kotlin/functional/BasicsHOFTests.kt[çözüm, windows=&quot;_blank].&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_kompozisyon&quot;&gt;Kompozisyon&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;package functional

import kotlin.test.Test
import kotlin.test.assertEquals


fun double(x: Int): Int = 2 * x
fun square(x: Int): Int = x * x
fun squareAndDouble1(x: Int) = double(square(x))

infix fun &amp;lt;A, B, C&amp;gt; ((A) -&amp;gt; B).compose(g: (B) -&amp;gt; C)
        : (A) -&amp;gt; C = { a -&amp;gt; g(this(a)) }

class CompositionTests {
    @Test
    fun composition_impure() {
        assertEquals(200, double(square(10)))
        assertEquals(200, squareAndDouble1(10))
    }

    @Test
    fun composition_pure() {
        val squareAndDouble = ::square compose ::double
        assertEquals(200, squareAndDouble(10))
    }

}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_saf_fonksiyonlar_ve_test_edilebilirlik&quot;&gt;saf fonksiyonlar ve test edilebilirlik&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;package functional

import java.io.ByteArrayOutputStream
import java.io.PrintStream
import java.lang.System.out
import java.lang.System.setOut
import kotlin.test.Test
import kotlin.test.assertEquals


var count = 0

//impure car une variable global subit un effet de bord
fun impure(value: Int): Int {
    count++
    return value + count
}

//impure car utilisation de la sortie standard qui fait muter le system
fun addOneAndLog(x: Int): Int {
    val result = x + 1
    println(&quot;New Value is $result&quot;)
    return result
}

//pure
fun addOne(x: Int) = (x + 1).run {
    Pair(this, &quot;New Value is $this&quot;)
}

class PureTests {
    @Test
    fun `impure fonction`() {
        assertEquals(3, impure(2))

        val standardOut = out
        val outputStreamCaptor = ByteArrayOutputStream()
        setOut(PrintStream(outputStreamCaptor))

        addOneAndLog(3)

        assertEquals(
            &quot;New Value is 4&quot;,
            outputStreamCaptor
                .toString()
                .trim()
        )
        setOut(standardOut)
    }

    @Test
    fun `pure fonction`() {
        addOne(3).run {
            assertEquals(4, first)
            assertEquals(&quot;New Value is 4&quot;, second)
        }
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect3&quot;&gt;
&lt;h4 id=&quot;_i̇stisna_işleme&quot;&gt;İstisna işleme&lt;/h4&gt;
&lt;div class=&quot;listingblock&quot;&gt;
&lt;div class=&quot;content&quot;&gt;
&lt;pre class=&quot;highlight&quot;&gt;&lt;code class=&quot;language-kotlin&quot; data-lang=&quot;kotlin&quot;&gt;package functional

import org.junit.jupiter.api.assertThrows
import kotlin.Result.Companion.failure
import kotlin.Result.Companion.success
import kotlin.test.Test
import kotlin.test.assertEquals

//NumberFormatException est un effet de bord qui rend la fonction impure
fun strToInt(str: String) = str.toInt()

//pure
fun strToIntOrNull(str: String) = try {
    str.toInt()
} catch (nfe: NumberFormatException) {
    null
}

//pure avec gestion de l&#39;exception plus élégante
fun strToIntResult(str: String): Result&amp;lt;Int&amp;gt; =
    try {
        success(str.toInt())
    } catch (nfe: NumberFormatException) {
        failure(nfe)
    }

class ExceptionHandlingTests {
    @Test
    fun impure() {
        assertThrows&amp;lt;NumberFormatException&amp;gt; { strToInt(&quot;foo&quot;) }
        assertEquals(1, strToInt(&quot;1&quot;))
    }

    @Test
    fun pure() {
        assertEquals(null, strToIntOrNull(&quot;foo&quot;))
        assertEquals(1, strToIntOrNull(&quot;1&quot;))
    }

    @Test
    fun `pure avec result`() {
        assertEquals(1, strToIntResult(&quot;1&quot;).getOrNull())
        assertEquals(
            &quot;For input string: \&quot;foo\&quot;&quot;,
            strToIntResult(&quot;foo&quot;)
                .exceptionOrNull()
                ?.message
        )
    }
}&lt;/code&gt;&lt;/pre&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div class=&quot;sect2&quot;&gt;
&lt;h3 id=&quot;_önemli_noktalar&quot;&gt;Önemli noktalar&lt;/h3&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Nesne yönelimli programlama, nesnelerle programlama yapmak anlamına gelir.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Fonksiyonel programlama fonksiyonlarla programlamayı ifade eder. Siz bir sorunu birkaç alt-soruna bölersiniz, bunları … ile modellersiniz. fonksiyonlar.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Yüksek dereceden fonksiyonlar diğer fonksiyonları girdi olarak kabul eder veya diğerlerini döndürür.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;geri dönüş değeri gibi çalışır Kategori teorisi kompozisyon teorisidir, ve onu anlamak için kullanırsın. İş planınızda işlevlerinizi nasıl oluşturabilirsiniz? Bir fonksiyonunun çıkış değeri, sadece giriş parametrelerine bağlıdır ve o Yan etkisi yok.&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Bir yan etki, bir fonksiyonun dış dünyada yaptığı şeydir. Bu&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Standart çıktıda bir günlük oluşturulabilir ya da bir genel değişkenin değeri değiştirilebilir. Fonksiyonel programlama temiz fonksiyonlar için işe yarar, ancak aynı zamanda da sağlar İmpür fonksiyonları pure fonksiyonlara dönüştürmek için araçlar Bir fonksiyonun etkilerini taşıyarak onu temiz (pure) hale getirebilirsiniz. geri dönüş değerinin kısmı&lt;/p&gt;
&lt;/div&gt;
&lt;div class=&quot;ulist&quot;&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Fonksiyonel programlama bir kompozisyon meselesidir.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div class=&quot;paragraph&quot;&gt;
&lt;p&gt;Hata yönetimi, yan etkilerin tipik bir örneğidir ve Kotlin size araçlar verir. fonksiyonel bir şekilde yönetmek için&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
